def main(files: list[object]) -> dict:
    import json, re
    def get(v, *names, default=None):
        for n in names:
            if isinstance(v, dict) and n in v and v[n] not in (None, ""):
                return v[n]
        return default
    docs = []
    errors = []
    for fi, f in enumerate(files or []):
        if not isinstance(f, dict):
            continue
        fname = str(get(f, "name", "filename", "file_name", default=f"文件{fi+1}"))
        url = str(get(f, "url", "remote_url", "download_url", default=""))
        content = get(f, "content", "text", "extract", default="")
        if not isinstance(content, str):
            try:
                content = json.dumps(content, ensure_ascii=False)
            except Exception:
                content = str(content)
        rows = []
        ctype = "unknown"
        head = content[:4000]
        # --- 表格类（CSV / 竖线 / 任意单字符分隔）解析 ---
        lines = [ln for ln in content.replace("\r\n", "\n").replace("\r", "\n").split("\n") if ln.strip()]
        sep = None
        if lines:
            for c in [",", "\t", "|", ";", "，"]:
                cnt = lines[0].count(c)
                if cnt >= 2 and all(ln.count(c) >= cnt - 2 for ln in lines[: min(8, len(lines))]):
                    sep = c
                    break
        if sep is not None:
            ctype = "table"
            def split_line(ln):
                out, cur, inq = [], "", False
                for ch in ln:
                    if ch == '"':
                        inq = not inq
                    elif ch == sep and not inq:
                        out.append(cur.strip())
                        cur = ""
                    else:
                        cur += ch
                out.append(cur.strip())
                return out
            header = None
            data_rows = 0
            for ln in lines:
                cells = split_line(ln)
                non_num = sum(1 for c in cells if not re.fullmatch(r"-?\d+(\.\d+)?%?", c))
                if header is None and len(cells) >= 2 and non_num >= max(1, len(cells) // 2):
                    header = cells
                    continue
                if header is not None and len(cells) == len(header):
                    rows.append({header[i]: cells[i] for i in range(len(header))})
                    data_rows += 1
            if header is None or data_rows == 0:
                ctype = "unknown"
                rows = []
        # --- 非表格：按行结构化 ---
        if ctype == "unknown":
            for ln in lines[:500]:
                m = re.match(r"^(.{1,30}?)[:：]\s*(.+)$", ln)
                if m:
                    rows.append({"行文本": ln, "键": m.group(1).strip(), "值": m.group(2).strip()})
                else:
                    rows.append({"行文本": ln})
            if len(rows) < 3:
                rows = [{"行文本": content[:2000]}]
            ctype = "document"
        stats = {"文件名": fname, "类型": ctype, "行数": len(rows), "字符数": len(content)}
        if not rows:
            errors.append({"文件名": fname, "问题": "未能解析出任何行"})
        docs.append({"文件名": fname, "类型": ctype, "行数据": rows, "统计": stats, "来源": url or "本地上传"})
    doc_stats = json.dumps({
        "文件数": len(docs),
        "解析成功": len([d for d in docs if d["行数据"]]),
        "异常": errors,
        "各文件统计": [d["统计"] for d in docs],
    }, ensure_ascii=False)
    return {"docs": docs, "doc_stats": doc_stats}

def main(docs: list[dict]) -> dict:
    import json, re
    # ---- 空间线：站点 -> 枢纽 映射（hub_registry）----
    HUB_MAP = {
        "青岛站": {"枢纽": "青岛站", "地铁": ["3号线青岛站", "1号线青岛站(换乘)"]},
        "青岛北站": {"枢纽": "青岛北站", "地铁": ["3号线青岛北站", "1号线青岛北站", "8号线青岛北站"]},
        "胶东机场": {"枢纽": "胶东机场", "地铁": ["8号线胶东机场站"]},
        "青岛胶东国际机场": {"枢纽": "胶东机场", "地铁": ["8号线胶东机场站"]},
    }
    MODE_KEYS = ["地铁", "国铁", "铁路", "高铁", "航空", "机场", "航班", "公交", "P+R", "停车", "单车"]
    def norm_time(s):
        m = re.search(r"(\d{1,2})[:：时](\d{1,2})", str(s))
        if not m:
            return None
        h, mi = int(m.group(1)), int(m.group(2))
        if h >= 24:
            h -= 24
        return h * 60 + mi
    def hour_bucket(minute, next_day=False):
        if minute is None:
            return None
        h = minute // 60
        key = f"{h:02d}-{h+1:02d}" if h < 23 else "23-24"
        if next_day and h < 5:
            return "夜-" + key
        return key
    def find_col(row, cands):
        for k, v in row.items():
            kk = re.sub(r"\s", "", str(k))
            for c in cands:
                if c in kk:
                    return k, v
        return None, None
    def detect_mode(docname, row):
        # 优先用文件名判方式（如"胶东机场专报"→航空），避免"地铁分担人次"等列名干扰
        for m in MODE_KEYS:
            if m in docname:
                return {"地铁": "地铁", "国铁": "国铁", "铁路": "国铁", "高铁": "国铁",
                        "航空": "航空", "机场": "航空", "航班": "航空", "公交": "公交",
                        "P+R": "P+R", "停车": "P+R", "单车": "单车"}[m]
        text = "".join(str(k) for k in row.keys())
        for m in MODE_KEYS:
            if m in text:
                return {"地铁": "地铁", "国铁": "国铁", "铁路": "国铁", "高铁": "国铁",
                        "航空": "航空", "机场": "航空", "航班": "航空", "公交": "公交",
                        "P+R": "P+R", "停车": "P+R", "单车": "单车"}[m]
        return "未知"
    hubs = {}
    issues = []
    for doc in docs or []:
        dname = doc.get("文件名", "")
        for row in doc.get("行数据", []):
            mode = detect_mode(dname, row)
            _, hub_raw = find_col(row, ["枢纽", "站点", "车站", "机场"])
            hub = HUB_MAP.get(str(hub_raw or "").strip(), {}).get("枢纽") if hub_raw else None
            if hub is None:
                for hk in HUB_MAP:
                    if hk in json.dumps(row, ensure_ascii=False) or hk in dname:
                        hub = hk
                        break
            if hub is None:
                continue
            hub_obj = hubs.setdefault(hub, {"方式": {}, "时段事件": {}})
            mode_obj = hub_obj["方式"].setdefault(mode, {"事件数": 0, "量级": 0.0})
            mode_obj["事件数"] += 1
            _, num_raw = find_col(row, ["人次", "人数", "吞吐", "客流", "发送量", "到达量"])
            if num_raw is not None:
                m = re.search(r"[\d.]+", str(num_raw))
                if m:
                    try:
                        mode_obj["量级"] += float(m.group())
                    except ValueError:
                        pass
            _, t1 = find_col(row, ["到达时间", "到站时间", "进站时间", "时间"])
            _, t2 = find_col(row, ["发车时间", "起飞时间", "出发时间", "开车时间"])
            for tv, nd in ((t1, False), (t2, False)):
                mi = norm_time(tv) if tv is not None else None
                bk = hour_bucket(mi, nd)
                if bk:
                    hub_obj["时段事件"][bk] = hub_obj["时段事件"].get(bk, 0) + 1
    # ---- 时间线：全枢纽时段对齐矩阵 ----
    all_buckets = sorted({b for h in hubs.values() for b in h["时段事件"]})
    time_matrix = {b: {hname: hobj["时段事件"].get(b, 0) for hname, hobj in hubs.items()} for b in all_buckets}
    peak = {}
    for hname, h in hubs.items():
        if h["时段事件"]:
            bk = max(h["时段事件"], key=lambda k: h["时段事件"][k])
            peak[hname] = {"高峰时段": bk, "事件数": h["时段事件"][bk]}
    # ---- 高峰叠加检测（干线层方式间的时段交集）----
    overlay = {}
    for hname, h in hubs.items():
        by_mode = {}
        for mode_obj_rows in [h["方式"]]:
            pass
        # 方式级时段在此前未细分，叠加检测退化为枢纽间/干线量级对比，留待明细扩展
        overlay[hname] = {"说明": "需方式级时段明细，本版按枢纽级时段对比"}
    result = {
        "枢纽数": len(hubs),
        "枢纽清单": sorted(hubs.keys()),
        "空间映射": {hub_name: {"方式统计": hub_obj["方式"]} for hub_name, hub_obj in hubs.items()},
        "时间对齐": {"时段": all_buckets, "矩阵": time_matrix},
        "高峰": peak,
        "叠加检测": overlay,
        "问题清单": issues,
    }
    summary = {
        "枢纽数": result["枢纽数"],
        "枢纽清单": result["枢纽清单"],
        "各枢纽方式统计": result["空间映射"],
        "高峰时段": peak,
        "时段矩阵规模": f"{len(all_buckets)}时段 x {len(hubs)}枢纽",
    }
    return {"fusion_result": result, "fusion_summary": json.dumps(summary, ensure_ascii=False)}

