def main(fusion_summary: str, analysis_text: str) -> dict:
    import json, re
    try:
        s = json.loads(fusion_summary)
        if not isinstance(s, dict):
            s = {"原始摘要": str(s)}
    except Exception:
        s = {"原始摘要": fusion_summary}
    heads = []
    for m in re.finditer(r"^#{1,3} .+$", analysis_text or "", flags=re.M):
        heads.append(m.group().strip())
    dups = [x for x in set(heads) if heads.count(x) > 1]
    if dups:
        raise ValueError("分析章节标题重复：" + ",".join(dups))
    def fmt(x):
        if isinstance(x, dict):
            return json.dumps(x, ensure_ascii=False, indent=1)
        if isinstance(x, list):
            return "、".join(str(i) for i in x[:20])
        return str(x)
    lines = ["# 多源客流融合分析报告", ""]
    lines.append("## 一、融合指标摘要")
    lines.append(fmt(s))
    lines.append("")
    lines.append("## 二、专题分析")
    lines.append((analysis_text or "").strip() or "（模型未返回分析正文）")
    lines.append("")
    report_md = "\n".join(lines).strip()
    return {"report_md": report_md}
